using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;
public sealed class RetroDepthFollowupValidation:MonoBehaviour {
 const BindingFlags F=BindingFlags.NonPublic|BindingFlags.Instance;DungeonPrototype d;RetroDungeonWallComposer c;List<string> results=new List<string>();public bool Done{get;private set;}public string Summary{get;private set;}
 object Call(string name,params object[] args){return typeof(DungeonPrototype).GetMethod(name,F).Invoke(d,args);}void Warp(int x,int y,int heading=0){Call("WarpPlayer",new Vector2Int(x,y),heading);}void Check(bool ok,string name){results.Add((ok?"PASS ":"FAIL ")+name);}
 Color32[] Frame(){var rt=d.RetroView.GetComponent<HelmetCRTWholeFrame>().WorldFrame;var previous=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);t.Apply();var values=t.GetPixels32();Destroy(t);RenderTexture.active=previous;return values;}
 int Changed(Color32[] a,Color32[] b){int n=0;for(int i=0;i<a.Length;i++)if(Math.Abs(a[i].r-b[i].r)+Math.Abs(a[i].g-b[i].g)+Math.Abs(a[i].b-b[i].b)>12)n++;return n;}
 public void Run(){StartCoroutine(Checks());}
 IEnumerator Checks(){c=FindFirstObjectByType<RetroDungeonWallComposer>();d=c.dungeon;var original=d.CaptureDungeonSave();var oldEncounter=d.enemyEncounterSettings;var quiet=Instantiate(oldEncounter);quiet.encounterDirectorEnabled=false;d.enemyEncounterSettings=quiet;var fixture=JsonUtility.FromJson<DungeonSaveData>(JsonUtility.ToJson(original));fixture.enemies.Clear();fixture.triggeredEncounters=new string[0];fixture.interactions.completedEvents.RemoveAll(id=>id.StartsWith("retro.pipe."));fixture.cell=d.mapSettings.startCell;fixture.heading=0;d.RestoreDungeonSave(fixture);yield return null;
 try{Check(original.enemies.Any(e=>string.IsNullOrEmpty(e.placementId)),"Fresh map includes ordinary enemies");var settings=c.settings;Check(settings.cloudParallax<settings.mountainParallax&&settings.mountainParallax<settings.bushParallax,"Cloud/mountain/bush apparent motion ordered by depth");var generated=c.transform.Find("Retro wall compositions");var materials=generated.GetComponentsInChildren<Renderer>().Select(r=>r.sharedMaterial).Distinct().ToArray();Check(materials.Where(m=>m.GetFloat("_Atmosphere")>0).Any(),"Mountains have configurable blue atmospheric perspective");Check(settings.normalMaps.All(n=>((UnityEditor.TextureImporter)UnityEditor.AssetImporter.GetAtPath(UnityEditor.AssetDatabase.GetAssetPath(n.normal))).textureType==UnityEditor.TextureImporterType.NormalMap),"All eleven supplied normal assets are imported as normals");Check(materials.Any(m=>m.GetFloat("_HasNormalMap")>.5f),"Actual normal maps bound to rendered walls");Material floor=null;foreach(Transform child in d.transform)if(child.name=="Floor")floor=child.GetComponent<Renderer>().sharedMaterial;Check(floor.GetTexture("_FloorWallDistance")!=null&&floor.GetVector("_FloorDistanceBounds").z>0,"Floor has wall-distance field for soft center fade");yield return new WaitForEndOfFrame();Check(floor.GetFloat("_PlanarReady")>.5f&&floor.GetTexture("_PlanarReflection")!=null,"Existing planar reflection capture ready");
 Warp(5,7);d.RetroView.transform.rotation=Quaternion.Euler(0,35,0);yield return null;yield return new WaitForEndOfFrame();var withDepth=Frame();var offsets=materials.ToDictionary(m=>m,m=>m.GetFloat("_Parallax"));foreach(var m in materials)m.SetFloat("_Parallax",0);yield return null;yield return new WaitForEndOfFrame();var flat=Frame();foreach(var pair in offsets)pair.Key.SetFloat("_Parallax",pair.Value);Check(Changed(withDepth,flat)>30,"GPU output responds to independent depth offsets");
 yield return (IEnumerator)Call("Move",1,0);yield return (IEnumerator)Call("Move",-1,0);yield return (IEnumerator)Call("Move",0,1);yield return (IEnumerator)Call("Move",0,-1);Check(d.RetroPlayerCell==new Vector2Int(5,7),"Forward/back and 90-degree turns preserve logical grid");Check(d.RetroView.transform.rotation==Quaternion.identity,"Turns return camera exactly to original heading");
 Warp(5,9);yield return null;yield return new WaitForSecondsRealtime(.8f);var frontal=c.GetComponentsInChildren<RetroDungeonPipe>().First(p=>p.pipeId=="retro.pipe.front.north");Warp(5,10);yield return null;yield return new WaitForSecondsRealtime(.7f);Check(frontal.SuccessfulSpawns==1,"Approaching frontal pipe emits existing enemy");Check((frontal.LastEmergenceOrigin-frontal.mouth.position).sqrMagnitude<.0001f,"Frontal enemy starts exactly at authored mouth");ScreenCapture.CaptureScreenshot("Captures/RetroDungeonExperiment/FrontalPipe.png");yield return new WaitForEndOfFrame();yield return null;d.RestoreDungeonSave(fixture);c.Build();yield return null;yield return null;Warp(17,12);yield return new WaitForSecondsRealtime(.7f);var upper=c.GetComponentsInChildren<RetroDungeonPipe>().First(p=>p.pipeId=="retro.pipe.demo");Check(upper.SuccessfulSpawns==1,"Top pipe emits existing enemy");Check(upper.LastEmergenceOrigin.y>upper.transform.position.y+1&&(upper.LastEmergenceOrigin-upper.mouth.position).sqrMagnitude<.0001f,"Top enemy emerges from upper rim instead of base");
 d.RestoreDungeonSave(fixture);c.Build();yield return null;yield return null;Warp(5,7);d.RetroView.transform.rotation=Quaternion.Euler(0,35,0);yield return null;yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot("Captures/RetroDungeonExperiment/DepthRoom.png");yield return new WaitForEndOfFrame();yield return null;Warp(5,2);yield return null;yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot("Captures/RetroDungeonExperiment/DepthCorridor.png");yield return new WaitForEndOfFrame();yield return null;d.RestoreDungeonSave(fixture);c.Build();yield return null;yield return null;Warp(5,10);yield return null;Warp(5,11);Call("TryEncounter");yield return new WaitForSecondsRealtime(.7f);Check(d.LaboratoryBattle&&!d.ExplorationMinimapVisible,"Rushing pipe enemy starts combat with minimap hidden");var homes=(Dictionary<int,Vector3>)typeof(DungeonPrototype).GetField("encounterHomes",F).GetValue(d);Check(homes.Count>0&&homes.Values.All(home=>Mathf.Abs(home.y)<.001f),"Interrupted emergence preserves a floor-aligned return position");
 Check(!UnityEditor.ShaderUtil.ShaderHasError(Resources.Load<Shader>("Shaders/RetroDungeonLayer")),"URP shader compiled without errors");
 }finally{d.enemyEncounterSettings=oldEncounter;d.RestoreDungeonSave(original);c.Build();Destroy(quiet);Summary=results.Count(r=>r.StartsWith("PASS"))+" passed / "+results.Count(r=>r.StartsWith("FAIL"))+" failed";File.WriteAllLines("Tests/RetroDepthFollowupResults.txt",new[]{Summary}.Concat(results));Done=true;Debug.Log("Retro depth followup: "+Summary);}
 }
